package com.example.zhttaskflow.base.uiimport androidx.compose.foundation.layout.PaddingValuesimport androidx.compose.foundation.layout.WindowInsetsimport androidx.compose.foundation.layout.calculateEndPaddingimport androidx.compose.foundation.layout.calculateStartPaddingimport androidx.compose.foundation.layout.statusBarsimport androidx.compose.runtime.Composableimport androidx.compose.ui.platform.LocalDensityimport androidx.compose.ui.platform.LocalLayoutDirectionimport androidx.compose.ui.unit.Dpimport androidx.compose.ui.unit.dp/** 全局 Edge-to-Edge inset 策略（唯一入口）。 */object TaskFlowInsetsPolicy {    val scaffoldContentWindowInsets: WindowInsets = WindowInsets(0, 0, 0, 0)}/** * 强制清零顶部内边距，只保留左右和底部的避让 * */@Composablefun rememberTaskFlowScaffoldContentPadding(    scaffoldPadding: PaddingValues,): PaddingValues {    val layoutDirection = LocalLayoutDirection.current    return PaddingValues(        start = scaffoldPadding.calculateStartPadding(layoutDirection),        end = scaffoldPadding.calculateEndPadding(layoutDirection),        top = 0.dp,        bottom = scaffoldPadding.calculateBottomPadding(),    )}@Composablefun rememberTaskFlowStateBoxContentPadding(): PaddingValues = PaddingValues(0.dp)/** * 计算当前设备状态栏的实际高度（dp 值），给业务页面的交互元素做顶部避让 * 沉浸式头部内避开状态栏的 top inset（Banner 图可全屏铺到顶，文字/按钮用此 padding）。 */@Composablefun rememberTaskFlowStatusBarTopInset(): Dp {    val density = LocalDensity.current    return with(density) {        WindowInsets.statusBars.getTop(this).toDp()    }}/** * 列表页面（LazyColumn 等）使用的标准化内边距，统一列表的左右留白和底部避让 * */@Composablefun rememberTaskFlowListLazyContentPadding(    scaffoldPadding: PaddingValues,    extraBottom: Dp = 0.dp,): PaddingValues {    //Scaffold 计算的底部 Tab 栏高度 + 可选的额外底部留白，    // 避免列表最后一项被底部 Tab 栏挡住，也可以给悬浮按钮等元素预留空间    val bottomInset = scaffoldPadding.calculateBottomPadding() + extraBottom    return PaddingValues(        //使用全局统一的页面水平内边距常量        start = TaskFlowUiConstants.PageHorizontalPadding,        end = TaskFlowUiConstants.PageHorizontalPadding,        top = 0.dp,        bottom = bottomInset,    )}